//! Header-level delivery evidence. Tags are declarations, not calibration.
use serde_json::{json,Value};use std::{process::Command,time::Duration};
pub fn inspect(path:&str)->Result<Value,String>{if path.is_empty()||path.starts_with('-')||path.contains("://"){return Err("delivery inspection requires local file path".into())}let file=std::fs::metadata(path).map_err(|e|format!("delivery stat: {e}"))?;if !file.is_file(){return Err("delivery path must be a file".into())}let bytes=super::process::capture(Command::new("ffprobe").args(["-v","error","-show_streams","-show_format","-of","json",path]),1024*1024,Duration::from_secs(30))?;let raw:Value=serde_json::from_slice(&bytes).map_err(|e|e.to_string())?;let mut streams=Vec::new();for s in raw["streams"].as_array().ok_or("no delivery streams")?{let mut out=serde_json::Map::new();for k in ["index","codec_type","codec_name","pix_fmt","width","height","color_range","color_space","color_transfer","color_primaries","bits_per_raw_sample","nb_frames","r_frame_rate","duration","sample_rate","channels","side_data_list"]{if let Some(v)=s.get(k){out.insert(k.into(),v.clone());}}streams.push(Value::Object(out));}
 let missing:Vec<_>=streams.iter().filter(|s|s["codec_type"]=="video").map(|s|{let keys:Vec<_>=["color_primaries","color_transfer","color_space","color_range"].iter().filter(|k|s.get(**k).is_none()||s[**k]=="unknown"||s[**k]=="unspecified").copied().collect();json!({"stream_index":s["index"],"absent_or_unspecified_color_fields":keys})}).collect();Ok(json!({"path":path,"bytes":file.len(),"container":raw["format"]["format_name"],"declared_duration":raw["format"]["duration"],"streams":streams,"tag_gaps":missing,"inspection":"header-only, no frame decode/count or color inference","note":"Container/codec tags and stream side data, when present, are file-declared. Frame-level HEVC SEI may require inspect_color_frame_metadata. Missing tags do not prove wrong pixels; present tags do not prove matching pixels, calibrated mastering, HDR compliance or display quality. No project settings changed."}))}

/// Decode the first video packet interval to inspect frame metadata, not pixels.
pub fn first_frame_metadata(path:&str)->Result<Value,String>{let header=inspect(path)?;let bytes=super::process::capture(Command::new("ffprobe").args(["-v","error","-select_streams","v:0","-read_intervals","%+#1","-show_frames","-show_entries","frame=side_data_list","-of","json",path]),1024*1024,Duration::from_secs(30))?;let raw:Value=serde_json::from_slice(&bytes).map_err(|e|e.to_string())?;let frames=raw["frames"].as_array().ok_or("no frame metadata result")?;let data:Vec<_>=frames.iter().filter_map(|f|f.get("side_data_list")).cloned().collect();Ok(json!({"path":path,"container":header["container"],"packet_interval":"first video packet, may decode zero frames on some codecs","decoded_frames":frames.len(),"frame_side_data":data,"note":"Explicit limited decode for frame metadata only. Missing metadata in this interval does not prove absence from all later frames. Values are file-declared, not measured mastering or proof of HDR correctness. No project mutation."}))}
